-- Sólo contenido editorial. No reejecuta los cortes confirmados ni modifica finanzas.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('corte-caja-faltante-1',$texto$Cerrar caja con un faltante de $1 justificado$texto$,'Finanzas',$texto$Comprobar que un cierre con diferencia exige justificación, documentar $1 de faltante y verificar que el cierre no descuente automáticamente dinero de la cuenta.$texto$,$texto$Cuenta administrativa identificable autorizada, caja de prueba activa CAJA-CORTE-TEST en MXN y saldo actual $1,150 después del ejemplo de cierre sin diferencia. Sin operaciones concurrentes. Si ya realizaste el faltante confirmado, consulta su corte cerrado; no vuelvas a abrir ni cerrar otro para repetirlo. Para reproducir desde cero prepara primero otra caja aislada siguiendo la guía Cerrar caja sin diferencia: de $1,000 a $1,150. No modificar el saldo inicial ni usar dinero real para simular una pérdida.$texto$,$texto$El propietario confirmó el rechazo al declarar $1,149 sin justificación y el cierre correcto al justificar: saldo inicial DEL NUEVO CORTE $1,150, sin movimientos nuevos, esperado $1,150, declarado $1,149, diferencia -$1 y saldo actual de la cuenta $1,150. El saldo inicial original DE LA CUENTA permanece $1,000. El corte documenta una discrepancia del conteo y no genera un egreso de $1. Las cancelaciones de modal y la consulta Excel se incluyen como controles adicionales recomendados, no como nuevas pruebas humanas confirmadas.$texto$,1,DATE '2026-10-15','CONFIRMADA');

INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['CUENTA_FINANCIERA_LEER','MOVIMIENTO_FINANCIERO_LEER','CORTE_CAJA_LEER','CORTE_CAJA_ADMINISTRAR']) WHERE g.slug='corte-caja-faltante-1';

INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('corte-caja-faltante-1',1,$texto$Identificar la caja y conservar el cierre anterior$texto$,$texto$Administración$texto$,$texto$Cuentas financieras y Cortes de caja$texto$,$texto$1. Entra a Administración → Finanzas → Cuentas financieras, busca CAJA-CORTE-TEST → Aplicar filtros. Comprueba Saldo actual $1,150; el Saldo inicial de la cuenta sigue siendo $1,000 y no se edita. 2. Entra a Administración → Finanzas → Movimientos financieros → Cortes de caja, selecciona la misma institución y caja → Aplicar filtros. Identifica el corte anterior cerrado con diferencia $0. 3. Conserva ese corte y sus movimientos de ingreso200/egreso50; no registres otros ni modifiques los anteriores para esta prueba. Si ya existe un corte abierto reservado a este ensayo, continúa en él sin abrir otro. 4. Si el faltante ya fue confirmado, abre su Ver detalle y revisa las pestañas Resumen, Apertura y Cierre y conciliación; usa los siguientes pasos sólo para consultar resultados, no para repetir la operación.$texto$,$texto$Saldo actual $1,150.00 y primer corte cerrado sin diferencia.$texto$,$texto$Caja identificada sin cambios financieros.$texto$,$texto$Usar una caja de prueba aislada. Si su saldo cambió por otra operación, no fuerces1150 ni cambies el saldo inicial: detén el ensayo y revisa qué ocurrió.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('corte-caja-faltante-1',2,$texto$Abrir un nuevo corte sin nuevos movimientos$texto$,$texto$Administración$texto$,$texto$Movimientos financieros → Cortes de caja → Abrir corte$texto$,$texto$1. Para una reproducción nueva entra a Administración → Finanzas → Movimientos financieros → Cortes de caja → Abrir corte. Selecciona Institución y Cuenta tipo caja CAJA-CORTE-TEST desde la ayuda; comprueba que no haya otro corte abierto. 2. Captura Observaciones de apertura: Prueba controlada de faltante de 1 peso. Pulsa Abrir corte: se abre un modal con institución, caja y observaciones. Cancelar dentro del modal permite corregir sin abrir; Cancelar del formulario vuelve al historial. 3. Cuando el resumen sea correcto pulsa Confirmar y abrir corte una vez. Anota el número NUEVO; no reutilices el primer corte cerrado ni registres ingresos o egresos después de esta apertura. 4. En Resumen comprueba Estado ABIERTO y Saldo inicial del sistema $1,150; en Apertura revisa fecha, responsable, último folio y observaciones. El saldo esperado no se revela antes de procesar el cierre.$texto$,$texto$Nuevo corte: saldo inicial del sistema $1,150.00; movimientos posteriores0.$texto$,$texto$Segundo corte preparado sin alterar la cuenta.$texto$,$texto$El sistema toma el saldo y folio vigentes al confirmar la apertura. No se captura1150 como otro ingreso y no se vuelve a registrar200/50.$texto$,$texto$/admin/cortes-caja/nuevo$texto$),
('corte-caja-faltante-1',3,$texto$Declarar $1,149 sin justificar todavía$texto$,$texto$Administración$texto$,$texto$Detalle del corte → Conteo y cierre$texto$,$texto$1. En el detalle del nuevo corte pulsa la pestaña Conteo y cierre; también puedes usar Ir a conteo y cierre desde Resumen. Si vienes del historial, entra a Administración → Finanzas → Movimientos financieros → Cortes de caja → filtra caja y Estado ABIERTO → Aplicar filtros → Contar y cerrar del número nuevo. 2. En Efectivo declarado captura1149.00 y deja Justificación de diferencia vacía, deliberadamente para comprobar la validación. 3. En Observaciones de cierre captura Prueba de validación de faltante. Comprueba que estás en la caja y corte del segundo ensayo, no en el cerrado sin diferencia. 4. Pulsa Conciliar y cerrar, revisa declarado $1,149 y ausencia de justificación en el modal y pulsa Confirmar y cerrar caja una vez. No se agregan ingresos ni egresos para efectuar el conteo.$texto$,$texto$Efectivo declarado $1,149.00; justificación vacía.$texto$,$texto$Intento de cierre con diferencia sin justificar.$texto$,$texto$Sólo un ensayo controlado debe omitir intencionalmente la justificación; en operación captura la explicación real y completa.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-faltante-1',4,$texto$Comprobar el rechazo y que el corte siga abierto$texto$,$texto$Administración$texto$,$texto$Detalle del corte → Conteo y cierre → Validación$texto$,$texto$1. Después de confirmar debe aparecer No se pudo cerrar el corte y Explica la diferencia entre el efectivo declarado y el saldo esperado. No debe mostrar cierre exitoso. 2. La pantalla abre automáticamente Conteo y cierre; verifica que conserve Efectivo declarado1149 y las observaciones para corregir sin volver a capturar todo. 3. Pulsa Resumen y comprueba Estado ABIERTO; regresa a Conteo y cierre sin recargar la página para mantener la captura no guardada. 4. No abras otro corte ni registres un egreso1 para quitar el aviso. El intento rechazado no cierra el corte ni modifica el saldo de la caja; continúa corrigiendo el mismo formulario.$texto$,$texto$Mensaje de justificación obligatoria; Estado ABIERTO.$texto$,$texto$Validación confirmada: el cierre sin motivo fue impedido.$texto$,$texto$El aviso es una validación de negocio, no un error técnico. No alteres el conteo para que coincida artificialmente y desaparezca la diferencia.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-faltante-1',5,$texto$Justificar y confirmar el mismo conteo$texto$,$texto$Administración$texto$,$texto$Detalle del corte → Conteo y cierre → Confirmación$texto$,$texto$1. En el mismo corte abierto y pestaña Conteo y cierre conserva Efectivo declarado1149.00; no cambies ese dato a1150 para evitar documentar el faltante. 2. En Justificación de diferencia captura Prueba controlada: faltante de 1 peso en el conteo físico. Conserva Observaciones de cierre: Prueba de validación de faltante. 3. Pulsa Conciliar y cerrar y revisa el modal: número/caja correctos, declarado $1,149, justificación y observaciones. Como control adicional puedes pulsar Cancelar dentro del modal para comprobar que conserva la captura sin cerrar. 4. Cuando todo coincida abre de nuevo el modal si lo cancelaste y pulsa Confirmar y cerrar caja una vez. Espera el mensaje Corte cerrado y conciliado correctamente.$texto$,$texto$Mismo declarado $1,149.00, ahora con explicación del faltante.$texto$,$texto$Corte cerrado después de justificar la diferencia.$texto$,$texto$No es una autorización para registrar dinero ficticio. En operación el motivo debe explicar el faltante real y su revisión administrativa.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-faltante-1',6,$texto$Revisar Resumen y Cierre y conciliación$texto$,$texto$Administración$texto$,$texto$Detalle cerrado → Resumen / Apertura / Cierre y conciliación$texto$,$texto$1. En el detalle cerrado abre Resumen: Estado CERRADO, Saldo esperado al cierre $1,150, Efectivo declarado $1,149 y Diferencia del conteo -$1 con explicación Faltante. 2. Abre Apertura: Saldo inicial del sistema $1,150 y las observaciones de este segundo corte. No confundirlo con el saldo inicial original de la cuenta1000 ni con el primer corte. 3. Abre Cierre y conciliación: comprueba fecha y usuario de cierre, Movimientos incluidos0, Ingresos del corte $0 y Egresos del corte $0. Debe decir Sin movimientos registrados durante este corte, sin inventar un rango de folios. 4. En esa misma pestaña lee Justificación de la diferencia y Observaciones de cierre; deben conservar los textos capturados. El corte cerrado no ofrece el formulario para modificar el conteo.$texto$,$texto$Diferencia = $1,149 - $1,150 = -$1.00; ingresos y egresos de este corte $0.$texto$,$texto$Faltante documentado con responsable, fecha y motivo.$texto$,$texto$El saldo esperado es una fotografía del cierre y la declaración es el conteo informado. El cierre no descuenta automáticamente el faltante de la cuenta.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-faltante-1',7,$texto$Consultar el faltante en el historial$texto$,$texto$Administración$texto$,$texto$Cortes de caja → Historial de conciliaciones$texto$,$texto$1. Pulsa Volver al historial, disponible al pie fuera de las pestañas. Filtra institución, Caja CAJA-CORTE-TEST y Estado CERRADO → Aplicar filtros; usa Desde/Hasta para la fecha de apertura si hace falta. 2. Identifica el segundo corte por su número: Saldo inicial $1,150, Diferencia del cierre -$1 y Esperado $1,150. El primer corte conserva inicial1000/diferencia0 y no debe modificarse. 3. Pulsa Ver detalle para regresar a Resumen y usa Apertura o Cierre y conciliación para consultar su información. Ver movimientos de la caja abre el libro de esa cuenta, que conserva también los movimientos de cortes anteriores. 4. Como control adicional recomendado, desde el historial exporta Excel con los mismos filtros y contrasta la diferencia y el saldo esperado. No existe un PDF específico del corte; los reportes financieros tienen un proceso separado.$texto$,$texto$Dos cortes históricos diferentes: primero sin diferencia, segundo con faltante $1.$texto$,$texto$Consulta clara sin interpretar -$1 como saldo total de la caja.$texto$,$texto$Ver movimientos filtra por cuenta, no elimina del libro operaciones de otros cortes. En este segundo corte no se registraron ingresos ni egresos.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-faltante-1',8,$texto$Verificar que la cuenta siga en $1,150$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Entra a Administración → Finanzas → Cuentas financieras, busca CAJA-CORTE-TEST → Aplicar filtros; consulta Saldo actual, no sólo Saldo inicial. 2. Debe seguir $1,150, sin decremento automático de $1. El saldo inicial original de la cuenta permanece $1,000 y no se cambia para conciliar este ejemplo. 3. Si necesitas revisar, abre Administración → Finanzas → Movimientos financieros y filtra la misma cuenta: deben conservarse los movimientos anteriores, sin un nuevo egreso1 causado por el cierre. No captures un movimiento manual para forzar que coincida con el conteo de1149. 4. Con saldo actual1150 y corte cerrado con diferencia-1 justificada, el caso queda concluido. El propietario confirmó esta prueba; no repetirla. Siguiente propuesta aún pendiente: sobrante de $1 y luego reportes financieros de pantalla, Excel y PDF.$texto$,$texto$Cuenta $1,150; diferencia del corte -$1; no hubo otro movimiento financiero.$texto$,$texto$Prueba confirmada: justificación obligatoria y cierre sin ajuste automático de saldos.$texto$,$texto$Una diferencia real requiere investigación y tratamiento autorizado por la escuela; este ejemplo no prescribe cómo contabilizar pérdidas reales ni sustituye ese procedimiento. No confirma todavía sobrantes ni reportes.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;

-- Actualizar navegación de la guía existente sin editar V97 ya aplicada.
UPDATE guia_proceso_paso s SET instrucciones=v.instrucciones
FROM guia_proceso g JOIN (VALUES
(3,$paso$1. Entra a Administración → Finanzas → Movimientos financieros → Cortes de caja, busca la caja del ensayo y comprueba que no tenga otro corte abierto; si ya existe uno reservado a este ejemplo, abre Contar y cerrar y continúa sin duplicarlo. 2. Para una reproducción nueva pulsa Abrir corte y selecciona Institución y Cuenta tipo caja desde la ayuda. En Observaciones de apertura captura «Prueba de corte con saldo inicial de 1000, ingreso de 200 y egreso de 50». 3. Pulsa Abrir corte y revisa el modal con institución, caja y observaciones. Cancelar dentro del modal permite corregir sin abrir; si coincide, pulsa Confirmar y abrir corte una sola vez. Cancelar del formulario sólo vuelve al historial. 4. En Resumen verifica Estado ABIERTO y Saldo inicial del sistema $1,000; abre Apertura para revisar fecha, usuario, folio inicial y observaciones. Anota el número del corte y deja Conteo y cierre sin capturar hasta registrar los movimientos.$paso$),
(6,$paso$1. Entra a Administración → Finanzas → Movimientos financieros → Cortes de caja, filtra institución, misma Caja y Estado ABIERTO → Aplicar filtros; identifica el número abierto para este ensayo. 2. Pulsa Contar y cerrar de ese registro: abre el detalle en Resumen, no cierra por sí solo. Verifica caja y saldo inicial del sistema $1,000 y pulsa la pestaña Conteo y cierre o el botón Ir a conteo y cierre. 3. En esa pestaña captura Efectivo declarado1150.00, deja Justificación de diferencia vacía porque coincide y escribe Observaciones de cierre: Prueba de cierre sin diferencia. 4. Revisa la captura sin registrar más movimientos. El saldo esperado y la diferencia no se revelan antes de procesar el cierre; no abras otro corte ni vuelvas a registrar200/50.$paso$),
(7,$paso$1. En el detalle abierto, pestaña Conteo y cierre, pulsa Conciliar y cerrar con el conteo ya capturado; se abre un modal y todavía no se ejecuta el cierre. 2. Revisa número/caja/plantel, Efectivo declarado $1,150, justificación y observaciones. El modal no adelanta el saldo esperado ni la diferencia. 3. Como control adicional recomendado pulsa Cancelar dentro del modal: sólo debe cerrarse, conservando la captura en Conteo y cierre y manteniendo el corte abierto. Cerrar después es un enlace al historial y no promete conservar campos sin guardar. 4. Corrige cualquier dato antes de confirmar; si coincide, pulsa nuevamente Conciliar y cerrar para reabrir el resumen de confirmación. No repitas esta captura en un corte que ya cerraste.$paso$),
(8,$paso$1. En el modal verifica la misma caja y Efectivo declarado $1,150; pulsa Confirmar y cerrar caja una sola vez y espera el resultado. 2. Debe aparecer Corte cerrado y conciliado correctamente. En la pestaña Resumen comprueba Estado CERRADO, Saldo esperado al cierre $1,150, Efectivo declarado $1,150 y Diferencia del conteo $0 con explicación Sin diferencia. 3. Abre Cierre y conciliación: revisa fecha y usuario, Movimientos incluidos2, Ingresos del corte $200 y Egresos del corte $50; en el ensayo original fueron Folios1 a2, aunque otra reproducción puede tener otros folios. 4. En esa misma pestaña consulta Observaciones de cierre: Prueba de cierre sin diferencia. Para consultar el inicio usa Apertura; los botones Volver al historial y Ver movimientos de la caja permanecen al pie fuera de las pestañas.$paso$),
(9,$paso$1. En el detalle cerrado pulsa Volver al historial, al pie fuera de las pestañas. Filtra institución, misma Caja y Estado CERRADO → Aplicar filtros; limita Desde/Hasta por fecha de apertura si es necesario. 2. Identifica el corte: Saldo inicial $1,000 y Diferencia del cierre Sin diferencia · $0.00, con Esperado: $1,150 debajo. Ese cero no significa que la cuenta quedó sin dinero. 3. Pulsa Ver detalle: Resumen muestra importes, Apertura muestra datos y observaciones iniciales, Cierre y conciliación muestra movimientos, responsable y observaciones finales. Ver movimientos de la caja abre el libro de esa cuenta sin modificar el corte. 4. Como comprobación adicional recomendada, vuelve al historial → Exportar Excel y contrasta los mismos filtros y cifras. No existe un botón PDF específico del corte; los reportes financieros se revisan por separado.$paso$),
(10,$paso$1. Entra a Administración → Finanzas → Cuentas financieras, busca la caja del ensayo → Aplicar filtros; no confundas Saldo actual con el saldo esperado de un corte histórico. 2. Verifica Saldo inicial de la cuenta $1,000 y Saldo actual $1,150. Si abres Editar, consulta Saldo actual disponible sin modificar ni guardar datos. 3. Si hay diferencias con el corte, entra a Movimientos financieros y filtra la misma caja para identificar operaciones posteriores: el corte conserva su fotografía y el saldo actual puede cambiar después. 4. Si no hubo otros movimientos y coincide1150, el caso queda concluido. Conserva el corte y sus dos movimientos sin repetirlos. El faltante justificado de $1 ya tiene su propia guía confirmada; el sobrante y los reportes financieros siguen pendientes.$paso$)
) v(numero,instrucciones) ON true
WHERE s.guia_id=g.id AND g.slug='corte-caja-sin-diferencia' AND s.numero=v.numero;

UPDATE guia_proceso_paso SET precaucion=$texto$Cerrar no crea un ingreso ni egreso. El faltante de $1 con justificación ya fue confirmado en su guía independiente; no repetir ni alterar este corte cerrado para simularlo.$texto$ WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='corte-caja-sin-diferencia') AND numero=8;
UPDATE guia_proceso_paso SET precaucion=$texto$No confundir cierre de caja con cierre mensual: no bloquea módulos ni meses. Faltante1 ya confirmado en su guía independiente; sobrantes, reportes, transferencias, retiros y compras no quedan confirmados con este ejemplo.$texto$ WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='corte-caja-sin-diferencia') AND numero=10;
UPDATE guia_proceso_paso SET precaucion=$texto$No repetir los ensayos de seguridad ya terminados. Cierre sin diferencia y faltante de $1 justificado ya tienen guías confirmadas independientes. Sobrante de $1 y reportes financieros siguen pendientes.$texto$ WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='seguridad-registro-validacion-pagos') AND numero=12;
UPDATE guia_proceso SET version_contenido=version_contenido+1,revisada_el=DATE '2026-10-15' WHERE slug IN ('corte-caja-sin-diferencia','seguridad-registro-validacion-pagos');
